// CourseCheckpoint One stage of a course's journey, pointing at a learning path template.
type CourseCheckpoint struct {
	// EffectiveTitle The title actually shown for this checkpoint — the override if one was set, otherwise the learning path's own title.
	EffectiveTitle string `json:"effective_title"`

	// LearningPathId The learning path template at this checkpoint.
	LearningPathId openapi_types.UUID `json:"learning_path_id"`

	// Position 1-based position of this checkpoint within the course.
	Position int `json:"position"`

	// Title The title override for this checkpoint, if one was set; absent when the checkpoint uses the learning path's own title.
	Title *string `json:"title,omitempty"`
}

// CourseDetail A single published course's learner-facing detail. It is always the
// latest published version's snapshot, rendered as an outline, so
// unpublished draft edits never change what a prospective learner sees.
type CourseDetail struct {
	// CheckpointCount Number of checkpoints in this published course version.
	CheckpointCount int `json:"checkpoint_count"`

	// Checkpoints The course's checkpoints, sorted by position ascending.
	Checkpoints []CourseOutlineCheckpoint `json:"checkpoints"`

	// CourseId Stable identifier for this course.
	CourseId openapi_types.UUID `json:"course_id"`

	// CreatedBy A reference to another MotifPath user, as it appears in any response
	// that points at a user (ADR-035). display_name is read from the
	// user's record when the response is built, never copied onto the
	// referencing entity, so a rename shows everywhere at once. A UserRef
	// appears only in responses the caller is already authorized to
	// receive.
	CreatedBy UserRef `json:"created_by"`

	// InstrumentIds The instruments this item is for, by Instrument.instrument_id. An
	// empty list means it suits every instrument (for example, music
	// theory). Every id must reference an existing instrument, and none
	// may repeat.
	InstrumentIds InstrumentIds `json:"instrument_ids"`

	// Language The language the course is written in, as a Language.code.
	Language string `json:"language"`

	// LessonCount Number of content nodes across this published course version's checkpoint learning paths. This is not an estimated duration.
	LessonCount int `json:"lesson_count"`

	// Level The level a student should be at to start this course.
	Level CourseDetailLevel `json:"level"`

	// PublishedAt Timestamp the latest published version was published at, or null if the course has never been published.
	PublishedAt *time.Time `json:"published_at,omitempty"`

	// Status The course's authoring status. A student's result is always published.
	Status CourseDetailStatus `json:"status"`

	// Summary Short description of the course.
	Summary string `json:"summary"`

	// ThumbnailUrl An image shown for this item in lists and cards. Absent when it has none.
	ThumbnailUrl *string `json:"thumbnail_url,omitempty"`

	// Title Title of the course.
	Title string `json:"title"`
}

// CourseDetailLevel The level a student should be at to start this course.
type CourseDetailLevel string

// CourseDetailStatus The course's authoring status. A student's result is always published.
type CourseDetailStatus string

// CourseEnrollment A student's enrollment in one course, tracking their active
// checkpoint independently of whichever course or path is
// currently focused.
type CourseEnrollment struct {
	// ActiveCheckpointPosition 1-based position of the active checkpoint within the course. Null once the enrollment is completed or abandoned.
	ActiveCheckpointPosition *int `json:"active_checkpoint_position"`

	// ActiveCheckpointStudentPathId The StudentPath for the checkpoint the student is currently working through. Null once the enrollment is completed or abandoned.
	ActiveCheckpointStudentPathId *openapi_types.UUID `json:"active_checkpoint_student_path_id"`

	// CheckpointCount Number of checkpoints in the pinned course version.
	CheckpointCount int `json:"checkpoint_count"`

	// CourseCreatedBy A reference to another MotifPath user, as it appears in any response
	// that points at a user (ADR-035). display_name is read from the
	// user's record when the response is built, never copied onto the
	// referencing entity, so a rename shows everywhere at once. A UserRef
	// appears only in responses the caller is already authorized to
	// receive.
	CourseCreatedBy UserRef `json:"course_created_by"`

	// CourseEnrollmentId Stable identifier for this enrollment.
	CourseEnrollmentId openapi_types.UUID `json:"course_enrollment_id"`

	// CourseId The enrolled course.
	CourseId openapi_types.UUID `json:"course_id"`

	// CourseLevel The course's level, as of the pinned version.
	CourseLevel CourseEnrollmentCourseLevel `json:"course_level"`

	// CourseSummary The course's summary, as of the pinned version.
	CourseSummary string `json:"course_summary"`

	// CourseThumbnailUrl The course's thumbnail, as of the pinned version. Absent when that version had none.
	CourseThumbnailUrl *string `json:"course_thumbnail_url,omitempty"`

	// CourseTitle The course's title, as of the pinned version.
	CourseTitle string `json:"course_title"`

	// CourseVersionNumber The CourseVersion this enrollment is pinned to.
	CourseVersionNumber int `json:"course_version_number"`

	// EnrolledAt Timestamp at which the student enrolled.
	EnrolledAt time.Time `json:"enrolled_at"`

	// Status active — in progress. completed — every checkpoint finished. abandoned — the student left this enrollment.
	Status CourseEnrollmentStatus `json:"status"`

	// Student A reference to another MotifPath user, as it appears in any response
	// that points at a user (ADR-035). display_name is read from the
	// user's record when the response is built, never copied onto the
	// referencing entity, so a rename shows everywhere at once. A UserRef
	// appears only in responses the caller is already authorized to
	// receive.
	Student UserRef `json:"student"`
}

// CourseEnrollmentCourseLevel The course's level, as of the pinned version.
type CourseEnrollmentCourseLevel string

// CourseEnrollmentStatus active — in progress. completed — every checkpoint finished. abandoned — the student left this enrollment.
type CourseEnrollmentStatus string

// CourseNotPublishableError Returned when a course can't be published because a checkpoint uses a learning path that is still a draft.
type CourseNotPublishableError struct {
	// DraftLearningPathIds The checkpoints' learning paths that are still drafts, in checkpoint order.
	DraftLearningPathIds []openapi_types.UUID `json:"draft_learning_path_ids"`

	// Message Human-readable reason for the refusal.
	Message string `json:"message"`
}

// CourseOutlineCheckpoint A checkpoint as shown to a prospective or enrolled student — title and item outline, never lesson content.
type CourseOutlineCheckpoint struct {
	// Items The checkpoint's items, in order, as a title-only outline.
	Items []CourseOutlineItem `json:"items"`

	// Position 1-based position of this checkpoint within the course.
	Position int `json:"position"`

	// Title The title shown for this checkpoint.
	Title string `json:"title"`
}

// CourseOutlineItem One content node's title within a course checkpoint's or a path's outline.
type CourseOutlineItem struct {
	// SectionLabel Optional label grouping this item with its immediate neighbors under a named section, carried through from the learning path.
	SectionLabel *string `json:"section_label,omitempty"`

	// Title Title of the content node.
	Title string `json:"title"`
}

// CourseVersion An immutable, permanent snapshot of a course's title, summary,
// level, language, and checkpoints at the moment it was published. Students
// and the catalog only ever read the latest CourseVersion, never
// the live draft.
type CourseVersion struct {
	// AvailableForNewEnrollments When false, this version can no longer be self-enrolled into, without retiring the course or requiring a newer version. Already-enrolled students are unaffected.
	AvailableForNewEnrollments bool `json:"available_for_new_enrollments"`

	// CourseId The course this version belongs to.
	CourseId openapi_types.UUID `json:"course_id"`

	// InstrumentIdsSnapshot The instrument_ids at the moment of publishing; empty means every instrument.
	InstrumentIdsSnapshot []openapi_types.UUID `json:"instrument_ids_snapshot"`

	// LanguageSnapshot The course's language at the moment of publishing, as a Language.code.
	LanguageSnapshot string `json:"language_snapshot"`

	// LevelSnapshot The course's level at the moment of publishing.
	LevelSnapshot CourseVersionLevelSnapshot `json:"level_snapshot"`

	// PublishedAt Timestamp at which this version was published.
	PublishedAt time.Time `json:"published_at"`

	// SummarySnapshot The course's summary at the moment of publishing.
	SummarySnapshot string `json:"summary_snapshot"`

	// ThumbnailUrlSnapshot The thumbnail_url at the moment of publishing; absent when there was none.
	ThumbnailUrlSnapshot *string `json:"thumbnail_url_snapshot,omitempty"`

	// TitleSnapshot The course's title at the moment of publishing.
	TitleSnapshot string `json:"title_snapshot"`

	// VersionNumber 1-based, increasing per course.
	VersionNumber int `json:"version_number"`
}

// CourseVersionLevelSnapshot The course's level at the moment of publishing.
type CourseVersionLevelSnapshot string

// CreateChallengeRequest Payload for creating a challenge within a content node. Exactly one
// of subject_skill_id or subject_concept_id must be set.
type CreateChallengeRequest struct {
	// PassThreshold The minimum score (as a percentage of exercises answered correctly)
	// required to pass this challenge.
	PassThreshold int `json:"pass_threshold"`

	// ShuffleExercises When true, the order in which this challenge's exercises are
	// returned varies per request. When false, exercises are always
	// returned in link order. Defaults to false — an assessment the
	// teacher wants comparable across attempts should keep a fixed order.
	ShuffleExercises *bool `json:"shuffle_exercises,omitempty"`

	// ShuffleOptions When true, each returned exercise's options are reordered per
	// request, independent of shuffle_exercises. Defaults to false.
	ShuffleOptions *bool `json:"shuffle_options,omitempty"`

	// SubjectConceptId The concept-kind KnowledgeNode this challenge assesses. Must be one of the parent
	// content node's linked concept_ids. Exactly one of
	// subject_skill_id/subject_concept_id must be set.
	SubjectConceptId *openapi_types.UUID `json:"subject_concept_id,omitempty"`

	// SubjectSkillId The skill-kind KnowledgeNode this challenge assesses. Must be one of the parent
	// content node's linked skill_ids. Exactly one of
	// subject_skill_id/subject_concept_id must be set — the subject is
	// the minimum required for gap detection, a challenge without one
	// produces analytically meaningless outcomes.
	SubjectSkillId *openapi_types.UUID `json:"subject_skill_id,omitempty"`

	// TimeThresholdMs An informational time expectation for this challenge, in
	// milliseconds. Purely advisory — never enforced, never affects
	// scoring or submission. When omitted, the value returned by
	// GET/list endpoints is computed as the sum of the challenge's
	// currently linked exercises' estimated_duration_seconds
	// (converted to milliseconds; an exercise with no estimate
	// contributes 0), recomputed on every read rather than stored, so
	// it always reflects the challenge's current exercise links. Set
	// this explicitly to override that computed value with the
	// teacher's own estimate.
	TimeThresholdMs *int `json:"time_threshold_ms,omitempty"`
}

// CreateContentNodeRequest Payload for creating a new content node.
type CreateContentNodeRequest struct {
	// Classification The three mandatory classification dimensions for a content node.
	// These dimensions are the minimum semantic layer required for gap
	// detection and the rules-based recommendation engine to function.
	// skill_ids/concept_ids reference existing KnowledgeNodes of kind
	// skill and concept respectively. Only admins create nodes; a teacher
	// who needs a missing one asks the team.
	// Every node must suit the content's instruments: it is for every
	// instrument, or for at least one of the content's instrument_ids.
	// Content for every instrument (empty instrument_ids) may use only
	// nodes for every instrument. A violation is rejected with the
	// offending skill_ids or concept_ids identified.
	Classification ClassificationInput `json:"classification"`

	// ContentType The media format of this content node. A diagram is not a
	// content_type of its own — embed one inline in rich_content via a
	// PromptNode, or attach it via ExpandedContent, on either type.
	ContentType CreateContentNodeRequestContentType `json:"content_type"`

	// InstrumentIds The instruments this item is for, by Instrument.instrument_id. An
	// empty list means it suits every instrument (for example, music
	// theory). Every id must reference an existing instrument, and none
	// may repeat.
	InstrumentIds InstrumentIds `json:"instrument_ids"`

	// LanguageCodes One or more Language.code values this content node is available
	// in. A single-element array containing "any" marks the content as
	// language-agnostic; "any" cannot be combined with other language
	// codes in the same array. Must not be empty — a node must be
	// explicitly tagged as either specific language(s) or
	// language-agnostic, never left unclassified.
	LanguageCodes []string `json:"language_codes"`

	// MediaUrl The video file or embeddable video URL students watch. Required
	// when content_type is video; must be absent when content_type is
	// article.
	// Must be an absolute http or https URL; any other scheme, or a
	// value that is not a URL at all, is rejected.
	MediaUrl *string `json:"media_url,omitempty"`

	// RichContent The article's body, authored with the same Tiptap-based rich
	// content model used for exercise prompts and expanded content —
	// may embed a diagram inline via a PromptNode, alongside text,
	// images, video, and audio. Required when content_type is article;
	// must be absent when content_type is video.
	RichContent *PromptDocument `json:"rich_content,omitempty"`

	// ThumbnailUrl An image shown for this item in lists and cards, as an absolute http or https URL (typically one returned by POST /media/upload-url with purpose thumbnail). Omitted means no thumbnail; on a replace or update, omitting it removes the current one.
	ThumbnailUrl *string `json:"thumbnail_url,omitempty"`

	// Title Human-readable title of the content node, displayed to students.
	Title string `json:"title"`
}

// CreateContentNodeRequestContentType The media format of this content node. A diagram is not a
// content_type of its own — embed one inline in rich_content via a
// PromptNode, or attach it via ExpandedContent, on either type.
type CreateContentNodeRequestContentType string

// CreateCourseEnrollmentRequest Payload for self-enrolling in a course.
type CreateCourseEnrollmentRequest struct {
	// CourseId The ID of the course to enroll in. Must be published and currently open to new enrollments.
	CourseId openapi_types.UUID `json:"course_id"`
}

// CreateCourseRequest Payload for creating a course as a draft.
type CreateCourseRequest struct {
	Checkpoints []struct {
		// LearningPathId The learning path template at this checkpoint. Must exist in the system. It may be a draft while the course is being built, but the course can't be published until it is published.
		LearningPathId openapi_types.UUID `json:"learning_path_id"`

		// Title Optional override shown for this checkpoint instead of the learning path's own title (e.g. "Stage 1: Open chords").
		Title *string `json:"title,omitempty"`
	} `json:"checkpoints"`

	// InstrumentIds The instruments this item is for, by Instrument.instrument_id. An
	// empty list means it suits every instrument (for example, music
	// theory). Every id must reference an existing instrument, and none
	// may repeat.
	InstrumentIds InstrumentIds `json:"instrument_ids"`

	// Language The language the course is written in, as a Language.code other than "any". A course is not localized: its title, summary and checkpoint titles are all in this language.
	Language string `json:"language"`

	// Level The level a student should be at to start this course, using the same five-value rubric applied to content nodes.
	Level CreateCourseRequestLevel `json:"level"`

	// Summary Short description of the course shown in the catalog.
	Summary string `json:"summary"`

	// ThumbnailUrl An image shown for this item in lists and cards, as an absolute http or https URL (typically one returned by POST /media/upload-url with purpose thumbnail). Omitted means no thumbnail; on a replace or update, omitting it removes the current one.
	ThumbnailUrl *string `json:"thumbnail_url,omitempty"`

	// Title Title of the course.
	Title string `json:"title"`
}

// CreateCourseRequestLevel The level a student should be at to start this course, using the same five-value rubric applied to content nodes.
type CreateCourseRequestLevel string

// CreateDiagramRequest Payload for creating a new diagram. Every position's string/fret vs.
// key, and every region's coordinates, must match the referenced
// instrument's family — the API rejects a request that mixes shapes or
// supplies the wrong shape for the instrument. Every playback step may
// only name positions of this request. Every per-language text
// (positions' custom_label and note, regions' description, playbacks'
// names) must be keyed by exactly the languages of names.
type CreateDiagramRequest struct {
	// Classification Classification for a new or updated Diagram. Diagrams share the
	// exact knowledge graph ContentNode and Exercise use (see
	// ClassificationInput) — not a separate tagging scheme — but carry no
	// difficulty_level; a diagram is a reusable shape, not a leveled
	// piece of content. Every node must be for every instrument or for
	// at least one of the diagram's instruments.
	Classification DiagramClassificationInput `json:"classification"`

	// Color The diagram's general marker color as #RRGGBB. Null (or omitted)
	// leaves it unrecorded.
	Color *string `json:"color,omitempty"`

	// DefaultPlaybackId Which of playbacks is the default; it must be the playback_id
	// of one of them, so the client supplies that playback's id.
	// Omitted or null makes the first playback the default. Must be
	// omitted or null when there are no playbacks.
	DefaultPlaybackId *openapi_types.UUID `json:"default_playback_id,omitempty"`

	// InstrumentIds The compatible instruments for this diagram. The first is the
	// immutable layout instrument; every selected instrument must have
	// matching coordinate geometry.
	InstrumentIds []openapi_types.UUID `json:"instrument_ids"`

	// Kind Whether the new diagram is a curated basic template or the
	// caller's own custom diagram. Omitted defaults to custom. Only an
	// admin may create a basic diagram. The caller is always recorded
	// as the creator; there is no way to create a diagram on another
	// user's behalf.
	Kind *CreateDiagramRequestKind `json:"kind,omitempty"`

	// LabelDisplay Which of a position's interval or note_name its marker shows by
	// default when reopened for authoring; hidden shows neither.
	// Omitted defaults to interval.
	LabelDisplay *CreateDiagramRequestLabelDisplay `json:"label_display,omitempty"`

	// Mode The mode of the diagram's key. Requires root_note. Null (or
	// omitted) records no key.
	Mode *DiagramMode `json:"mode,omitempty"`

	// Names The diagram's name in each of its languages. A basic diagram
	// needs a name in every language MotifPath offers; a custom one
	// needs at least one.
	Names LocalizedNames `json:"names"`

	// Playbacks The diagram's playbacks, in order. Every position_id a step
	// names must be the position_id of one of this request's
	// positions, so a position that plays must be given its
	// position_id by the client. Omitted means no playback.
	Playbacks *[]DiagramPlaybackInput `json:"playbacks,omitempty"`

	// Positions Every marked position in this diagram, in the coordinate shape
	// matching the referenced instrument's family. position_id may be
	// supplied by the client or left for the server to assign.
	Positions []DiagramPosition `json:"positions"`

	// Regions The diagram's highlighted regions, in drawing order, in the
	// coordinate shape matching the instrument's family. Omitted means
	// none. region_id may be supplied or left for the server to assign.
	Regions *[]DiagramRegion `json:"regions,omitempty"`

	// RootNote The root note this diagram is authored against (e.g. "A"). Null
	// (or omitted) leaves it unrecorded.
	RootNote *string `json:"root_note,omitempty"`
}

// CreateDiagramRequestKind Whether the new diagram is a curated basic template or the
// caller's own custom diagram. Omitted defaults to custom. Only an
// admin may create a basic diagram. The caller is always recorded
// as the creator; there is no way to create a diagram on another
// user's behalf.
type CreateDiagramRequestKind string

// CreateDiagramRequestLabelDisplay Which of a position's interval or note_name its marker shows by
// default when reopened for authoring; hidden shows neither.
// Omitted defaults to interval.
type CreateDiagramRequestLabelDisplay string

// CreateExerciseRequest Payload for creating a standalone, reusable exercise.
// Every skill and concept must suit the exercise's instruments: it is
// for every instrument, or for at least one of the exercise's
// instrument_ids. An exercise for every instrument (empty
// instrument_ids) may use only nodes for every instrument. A violation
// is rejected with the offending skill_ids or concept_ids identified —
// the same rule content nodes and diagrams follow.
type CreateExerciseRequest struct {
	// AudioUrl The stimulus audio for this exercise. Required when exercise_type
	// is audio_recognition; absent otherwise.
	AudioUrl *string `json:"audio_url,omitempty"`

	// ConceptIds The id(s) of the concept node(s) this exercise addresses.
	// Must not be empty; each id must reference an existing concept-kind node.
	ConceptIds []openapi_types.UUID `json:"concept_ids"`

	// DiagramRef A single prebuilt diagram as this exercise's stimulus, replacing
	// image_url. Only meaningful when exercise_type is
	// image_recognition. Its correct_position_ids must be set (or the
	// deprecated correct_intervals) — for a fretted diagram, every
	// fretboard cell of its answer window becomes one of this
	// exercise's options automatically (see Option.fret_cell);
	// options must be omitted when this is given. Mutually exclusive with image_url and
	// diagram_stack_ref.
	DiagramRef *DiagramRef `json:"diagram_ref,omitempty"`

	// DiagramStackRef Two or more composited prebuilt diagrams as this exercise's
	// stimulus, replacing image_url. Only meaningful when
	// exercise_type is image_recognition. Each entry's own
	// correct_intervals must be set; options must be omitted when
	// this is given. Mutually exclusive with image_url and
	// diagram_ref.
	DiagramStackRef *DiagramStackRef `json:"diagram_stack_ref,omitempty"`

	// EstimatedDurationSeconds Authoring estimate of the time a student needs to attempt this
	// exercise once. Optional — used to fit practice sessions and
	// challenges to a student's available time.
	EstimatedDurationSeconds *int `json:"estimated_duration_seconds,omitempty"`

	// ExerciseType The type of practice interaction, which determines how its
	// options are authored and rendered. text_response and
	// audio_recognition options carry a text label; image_recognition
	// options carry a region on image_url (or are derived from
	// diagram_ref/diagram_stack_ref — see below); image_choice
	// options each carry their own image_url or diagram_ref;
	// audio_selection options each carry their own audio_url.
	ExerciseType CreateExerciseRequestExerciseType `json:"exercise_type"`

	// ImageUrl The stimulus image for this exercise. For exercise_type
	// image_recognition, required unless diagram_ref or
	// diagram_stack_ref is given instead; absent otherwise.
	ImageUrl *string `json:"image_url,omitempty"`

	// InstrumentIds The instruments this exercise is for. Omit or leave empty for
	// every instrument (for example, a theory or ear-training
	// question).
	InstrumentIds *InstrumentIds `json:"instrument_ids,omitempty"`

	// LanguageCodes One or more Language.code values this exercise is available in.
	// A single-element array containing "any" marks the exercise as
	// language-agnostic; "any" cannot be combined with other language
	// codes in the same array. Must not be empty. Tagged independently
	// of any content node's own language tagging, since an exercise
	// can be reused across multiple content nodes.
	LanguageCodes []string `json:"language_codes"`

	// Options The exercise's selectable answer choices. At least one option
	// must have is_correct set to true — an exercise with no correct
	// option cannot be graded. Required unless exercise_type is
	// image_recognition and diagram_ref or diagram_stack_ref is
	// given, in which case options are derived automatically from the
	// diagram's positions and must be omitted here.
	Options *[]Option `json:"options,omitempty"`

	// Prompt A structured rich-text document, authored with MotifPath's
	// Tiptap-based content-authoring editor and persisted exactly as the
	// editor produces it (ProseMirror JSON). Used for an exercise's
	// prompt, rich_text expanded content, and an exercise's
	// remediation_targets rich content — the same document shape across
	// all three, though which PromptNode types a given surface's own
	// toolbar can actually produce varies (an exercise prompt's toolbar
	// does not offer audio/video embeds; expanded content and remediation
	// content may). Always has type "doc" at the root, with the
	// document's block-level content nested beneath it.
	Prompt PromptDocument `json:"prompt"`

	// RemediationTargets Content to recommend a student who answers this specific
	// exercise incorrectly, in priority order. Empty or omitted means
	// no remediation is configured for this exercise.
	RemediationTargets *[]RemediationTarget `json:"remediation_targets,omitempty"`

	// SkillIds The id(s) of the skill node(s) this exercise targets,
	// independent of any challenge or content node it may also be
	// linked to. Must not be empty; each id must reference an
	// existing skill-kind node.
	SkillIds []openapi_types.UUID `json:"skill_ids"`

	// Title A short, authoring-only name for this exercise (e.g. "Alternate
	// picking — descending run"), used to identify it in authoring
	// tools. Not shown to students.
	Title string `json:"title"`
}

// CreateExerciseRequestExerciseType The type of practice interaction, which determines how its
// options are authored and rendered. text_response and
// audio_recognition options carry a text label; image_recognition
// options carry a region on image_url (or are derived from
// diagram_ref/diagram_stack_ref — see below); image_choice
// options each carry their own image_url or diagram_ref;
// audio_selection options each carry their own audio_url.
type CreateExerciseRequestExerciseType string

// CreateExpandedContentRequest Payload for attaching an expositive item to a content node. The
// trigger and hide fields used depend on the parent content node type:
// video nodes use trigger_at_seconds + hide_at_seconds; article nodes use
// trigger_at_paragraph + duration_ms. Mixing fields across groups is invalid.
// These timing fields apply identically regardless of content_type —
// timing is a property of when the item appears, independent of what
// it contains.
type CreateExpandedContentRequest struct {
	// Caption Optional caption displayed alongside the item.
	Caption *string `json:"caption,omitempty"`

	// ContentType The format of the expanded content item. image and gif require
	// media_url; rich_text requires rich_content instead; diagram
	// requires diagram_ref or diagram_stack_ref instead — each is
	// mutually exclusive with the others.
	ContentType CreateExpandedContentRequestContentType `json:"content_type"`

	// DiagramRef A single prebuilt diagram, shown per its layer/styling/playback
	// config, triggered at the same video timestamp or article
	// paragraph any other expanded content item would be. Required
	// when content_type is diagram and diagram_stack_ref is absent;
	// must be absent otherwise.
	DiagramRef *DiagramRef `json:"diagram_ref,omitempty"`

	// DiagramStackRef Two or more prebuilt diagrams composited in one view. Required
	// when content_type is diagram and diagram_ref is absent; must be
	// absent otherwise.
	DiagramStackRef *DiagramStackRef `json:"diagram_stack_ref,omitempty"`

	// DurationMs Article nodes only. How long to display this item in milliseconds
	// after it is triggered. Must be absent for video nodes.
	DurationMs *int `json:"duration_ms,omitempty"`

	// HideAtSeconds Video nodes only. The video timestamp (in seconds) at which to hide
	// this item. Must be greater than trigger_at_seconds. Must be absent
	// for article nodes.
	HideAtSeconds *int `json:"hide_at_seconds,omitempty"`

	// MediaUrl External URL of the image or GIF to display. Required when
	// content_type is image or gif; must be absent otherwise.
	MediaUrl *string `json:"media_url,omitempty"`

	// RichContent Rich content authored with the Tiptap-based content editor,
	// which may embed video, audio, or a diagram alongside text and
	// images — no separate video/audio/diagram content_type is
	// needed for an *inline* embed (see PromptNode). Required when
	// content_type is rich_text; must be absent otherwise.
	RichContent *PromptDocument `json:"rich_content,omitempty"`

	// TriggerAtParagraph Article nodes only. The 1-based paragraph index at which to show
	// this item. Must be absent for video nodes.
	TriggerAtParagraph *int `json:"trigger_at_paragraph,omitempty"`

	// TriggerAtSeconds Video nodes only. The video timestamp (in seconds) at which to show
	// this item. Must be absent for article nodes.
	TriggerAtSeconds *int `json:"trigger_at_seconds,omitempty"`
}

// CreateExpandedContentRequestContentType The format of the expanded content item. image and gif require
// media_url; rich_text requires rich_content instead; diagram
// requires diagram_ref or diagram_stack_ref instead — each is
// mutually exclusive with the others.
type CreateExpandedContentRequestContentType string

// CreateInstrumentRequest Payload for creating a new instrument. Only its names, default voice
// and icon can change afterwards (see updateInstrument); there is no delete endpoint, and
// changing family or string/key shape after Diagrams exist against it
// is a deliberately open question.
type CreateInstrumentRequest struct {
	// DefaultVoiceId The Voice that plays this instrument's diagrams by default. Must
	// be an existing voice of the same family.
	DefaultVoiceId string `json:"default_voice_id"`

	// Family Which coordinate shape Diagrams against this instrument will use.
	Family CreateInstrumentRequestFamily `json:"family"`

	// Icon The picture that stands for the instrument. Omitted gives the
	// generic icon of its family (fretted or keyboard).
	Icon *InstrumentIcon `json:"icon,omitempty"`

	// KeyRange Required when family is keyboard; must be absent when family is fretted.
	KeyRange *struct {
		// Highest Note name of the highest key (e.g. "C8").
		Highest string `json:"highest"`

		// Lowest Note name of the lowest key (e.g. "A0").
		Lowest string `json:"lowest"`
	} `json:"key_range,omitempty"`

	// Names The instrument's name in every language MotifPath offers — an
	// instrument is shared by every user, so every language is
	// required.
	Names LocalizedNames `json:"names"`

	// StringCount Required when family is fretted; must be absent when family is keyboard.
	StringCount *int `json:"string_count,omitempty"`

	// Tuning Open-string pitch per string, with its octave, lowest string
	// first (e.g. ["E2", "A2", "D3", "G3", "B3", "E4"]). Required when
	// family is fretted, with length equal to string_count; must be
	// absent when family is keyboard.
	Tuning *[]Pitch `json:"tuning,omitempty"`
}

// CreateInstrumentRequestFamily Which coordinate shape Diagrams against this instrument will use.
type CreateInstrumentRequestFamily string

// CreateKnowledgeEdgeRequest Payload for linking two knowledge nodes.
type CreateKnowledgeEdgeRequest struct {
	// FromId The node the edge leaves. For applies, a skill.
	FromId openapi_types.UUID `json:"from_id"`

	// Level Required for requires; must be absent for applies.
	Level *MasteryLevel `json:"level,omitempty"`

	// ToId The node the edge arrives at. For applies, a concept. Never the same node as from_id.
	ToId openapi_types.UUID `json:"to_id"`

	// Type applies — the skill (from) uses the concept (to); only skill →
	// concept, never with a level. requires — from needs to at level or
	// above; any kind to any kind, always with a level, and requires edges
	// never form a cycle. requires informs practice and recommendations;
	// it never locks content or blocks practice. A requires edge counts
	// for an instrument only when both of its nodes are for that
	// instrument. An applies edge never implies a requirement; the same
	// two nodes may carry both.
	Type KnowledgeEdgeType `json:"type"`
}

// CreateKnowledgeNodeRequest Payload for creating a skill or concept.
