// practised, is not due, and is not yet fluent; new = it has not been practised yet;
// warm_up = something already known, played first with the instrument in hand, below the
// student's edge and outside the evidence: its takes are not sent as practice.item_answered;
// application = one play-along at the end of a session of 10 minutes or more, applying a
// skill the session's focus items practised (or, with none, another skill of the student's
// paths), and evidence like any other take; review_ahead = a known item coming due within the
// week, reviewed before it falls due, when nothing else is due; stretch = an unseen item of a
// node the student is ready to start, the skills of their paths first, when nothing else is due
// or past the new share.
type PracticePickReason string

// PracticeSessionItem One item of a composed session, with what the client needs to present it. Exactly
// one of fretboard_cell, exercise, play_along and diagram_shape is present, matching
// kind.
type PracticeSessionItem struct {
	// DiagramShape Present when kind is diagram_shape. The client loads the diagram to draw it, with
	// its labels hidden, and gives instant feedback from it and from shape, graded the
	// way the server grades. The drill is the way of asking the shape has the fewer right
	// answers so far, name_the_shape on a tie.
	DiagramShape *struct {
		// AskedInterval For find_the_degree: the degree to tap, picked at random among the shape's
		// intervals other than its root. Null for name_the_shape.
		AskedInterval *ShapeInterval `json:"asked_interval"`

		// DiagramId The catalog diagram whose shape is asked.
		DiagramId openapi_types.UUID `json:"diagram_id"`

		// Drill How a diagram shape is asked. name_the_shape = the shape is shown without its name and the
		// student picks it among its family's members; find_the_degree = the shape is shown with its
		// root marked and its other positions unlabelled, and the student taps the asked degree.
		Drill DiagramShapeDrill `json:"drill"`

		// LayoutInstrumentId The instrument whose fretboard layout and tuning the diagram is drawn on, so a
		// tap check can be shown before the diagram has loaded.
		LayoutInstrumentId openapi_types.UUID `json:"layout_instrument_id"`

		// Options For name_the_shape: every member of the shape's family, in the catalog's
		// order (at least two), including members that have no shape at this root, so
		// the choices never narrow the answer down. The names never mention the root, so
		// the root shown never gives the answer away either. Empty for find_the_degree.
		Options []struct {
			// Name The member's name in the student's language, such as "A shape".
			Name string `json:"name"`

			// Shape The member's key, sent back as the answer.
			Shape string `json:"shape"`
		} `json:"options"`

		// Shape The member of its family this diagram is, by its key in the practice drill
		// catalog: the right answer to name_the_shape, one of the options' shape.
		Shape string `json:"shape"`

		// ShapeFamily The shape's family in the practice drill catalog, such as caged-grip.
		ShapeFamily string `json:"shape_family"`
	} `json:"diagram_shape,omitempty"`

	// EstimatedSeconds About how long the item takes, used to fit the session to its minutes. An exercise
	// takes its estimated_duration_seconds, or 30 seconds without one.
	EstimatedSeconds int `json:"estimated_seconds"`

	// Exercise A reusable, standalone practice item classified by skill/concept
	// tree references and independent of any single challenge. The
	// exercise_id is the value the SPA supplies in exercise-family
	// tracking events. An exercise is checked by option selection: the
	// student's selected option ID(s) must match the option(s) marked
	// is_correct.
	Exercise *Exercise `json:"exercise,omitempty"`

	// FretboardCell Present when kind is fretboard_cell. The drill is the way of asking the cell has
	// the fewer right answers so far, name_the_note on a tie.
	FretboardCell *struct {
		// Drill How a fretboard cell is asked. name_the_note = the cell is shown and the student names
		// its note; find_the_note = the note and string are named and the student taps the cell.
		Drill FretboardDrill `json:"drill"`

		// Fret The cell's fret; 0 is the open string.
		Fret int `json:"fret"`

		// LayoutInstrumentId The instrument whose fretboard layout and tuning the cell belongs to.
		LayoutInstrumentId openapi_types.UUID `json:"layout_instrument_id"`

		// String The cell's string, 1 being the highest-pitched.
		String int `json:"string"`
	} `json:"fretboard_cell,omitempty"`

	// ItemKey Stable, readable identifier of a practice item: the smallest thing whose knowledge is
	// tracked. Every answer, rating and review points at one. The prefix is the item kind:
	//
	// - fretboard_cell:<layout instrument id>:<string>:<fret> — a generated fretboard cell.
	//   The instrument is the one whose fretboard layout the cell belongs to, so instruments
	//   that share a layout share the cell. Strings are numbered from 1, the highest-pitched;
	//   fret 0 is the open string.
	// - exercise:<exercise id> — an authored exercise.
	// - play_along:<diagram id> — playing a diagram along with its playback, at a tempo.
	// - chord_change:<from diagram id>:<to diagram id> — changing between two chord diagrams.
	// - diagram_shape:<diagram id> — a catalog shape recalled in the head: naming it among its
	//   family, or finding one of its degrees. One diagram is one item: the same shape in
	//   another key has other positions, so it is another item.
	//
	// Item kinds are an open set: a new kind adds its own prefix and key scheme here, a
	// grader, and its golden cases.
	ItemKey PracticeItemKey `json:"item_key"`

	// Kind The kind of a practice item, the prefix of its item key. The set is open: a new kind
	// is added with its key scheme, grader and golden cases.
	Kind PracticeItemKind `json:"kind"`

	// Level How well a student knows an item, or a knowledge node, derived from the evidence.
	// new = never practised; learning = practised, not yet accurate; accurate = at least 3
	// counted attempts with accuracy of 0.8 or more; fluent = at least 5 counted attempts,
	// accuracy of 0.9 or more and fluency of 0.8 or more; retained = fluent and holding up
	// over long reviews.
	Level KnowledgeLevel `json:"level"`

	// NodeId The knowledge node this pick serves, shown with its reason (for example the
	// node a stretch item starts). Null when the reason needs none.
	NodeId *openapi_types.UUID `json:"node_id"`

	// PlayAlong Present when kind is play_along.
	PlayAlong *struct {
		// BestCleanTempoBpm The student's best clean tempo since their latest teacher review. Null when
		// they have no clean take yet.
		BestCleanTempoBpm *int `json:"best_clean_tempo_bpm"`

		// DiagramId The diagram played along with.
		DiagramId openapi_types.UUID `json:"diagram_id"`

		// StartTempoBpm The tempo to play this take at. For a warm-up, about 80% of the student's
		// best clean tempo; otherwise the tempo ladder's current step.
		StartTempoBpm int `json:"start_tempo_bpm"`

		// TargetTempoBpm The tempo the item aims for, the tempo of the diagram's default playback.
		TargetTempoBpm int `json:"target_tempo_bpm"`
	} `json:"play_along,omitempty"`

	// Reason Why the session composer put an item in a session, shown to the student.
	// teacher_suggested = a teacher asked for it; due = its review is due; weak = it has been
	// practised, is not due, and is not yet fluent; new = it has not been practised yet;
	// warm_up = something already known, played first with the instrument in hand, below the
	// student's edge and outside the evidence: its takes are not sent as practice.item_answered;
	// application = one play-along at the end of a session of 10 minutes or more, applying a
	// skill the session's focus items practised (or, with none, another skill of the student's
	// paths), and evidence like any other take; review_ahead = a known item coming due within the
	// week, reviewed before it falls due, when nothing else is due; stretch = an unseen item of a
	// node the student is ready to start, the skills of their paths first, when nothing else is due
	// or past the new share.
	Reason PracticePickReason `json:"reason"`
}

// PracticeSessionPlan A composed practice session. Not stored: it exists only in this response and in the
// practice.session_started event the client sends when the student starts it.
type PracticeSessionPlan struct {
	// FeltQuestions The timed drill templates, at most two, to ask "How did it feel?" about when the
	// session ends: those in this plan with the fewest felt-rated sessions so far, fewest
	// first. The client asks only about the ones the student actually practised in the
	// session. Empty when the plan has no timed drill, as with play-alongs only.
	FeltQuestions []string `json:"felt_questions"`

	// InstrumentId The instrument in hand, or null for a session in the head.
	InstrumentId *openapi_types.UUID `json:"instrument_id"`

	// Items The items to practise, in order.
	Items []PracticeSessionItem `json:"items"`

	// Minutes The time the session was composed for, in minutes.
	Minutes int `json:"minutes"`

	// PracticeSessionId New identifier for this session, carried by every practice.* event it produces.
	PracticeSessionId openapi_types.UUID `json:"practice_session_id"`

	// TapCheckDue True when the plan has a fretboard cell or a diagram shape and the student has
	// done no tap check in the last 30 days, or never. The client then offers the tap
	// check before the first item; the student may skip it, and their answers are then
	// judged on the whole latency.
	TapCheckDue bool `json:"tap_check_due"`
}

// PracticeSummary The home for one instrument, derived from the student's evidence.
type PracticeSummary struct {
	// Groups Every practice node, grouped by area, then a group for nodes that suit any
	// instrument.
	Groups []PracticeNodeGroup `json:"groups"`

	// InstrumentId The instrument summarised, or null for nodes that suit any instrument only.
	InstrumentId *openapi_types.UUID `json:"instrument_id"`

	// NextSteps The top three next steps, in order.
	NextSteps []PracticeNextStep `json:"next_steps"`

	// NextStepsTotal How many next steps there are in all, for "see all".
	NextStepsTotal int `json:"next_steps_total"`

	// PracticeDaysLast7 On how many of the last 7 calendar days, in the given time zone, the student
	// finished a practice session: ended without leaving early, and not abandoned (no
	// practice event for the session's planned minutes plus 15) with the summarised
	// instrument in hand. A session on another instrument counts on that instrument's
	// summary, not this one. Never a streak: a missed day is never a reset.
	PracticeDaysLast7 int `json:"practice_days_last_7"`

	// ProgressThisWeek Skills that improved over the last 7 days, most improved first. Empty when none did.
	ProgressThisWeek []SkillProgress `json:"progress_this_week"`

	// StudentInstrumentIds The student's instruments, inferred from the paths and courses they're enrolled
	// in; a path or course for every instrument adds none. The home shows one tab per
	// instrument.
	StudentInstrumentIds []openapi_types.UUID `json:"student_instrument_ids"`
}

// PromptDocument A structured rich-text document, authored with MotifPath's
// Tiptap-based content-authoring editor and persisted exactly as the
// editor produces it (ProseMirror JSON). Used for an exercise's
// prompt, rich_text expanded content, and an exercise's
// remediation_targets rich content — the same document shape across
// all three, though which PromptNode types a given surface's own
// toolbar can actually produce varies (an exercise prompt's toolbar
// does not offer audio/video embeds; expanded content and remediation
// content may). Always has type "doc" at the root, with the
// document's block-level content nested beneath it.
type PromptDocument struct {
	// Content The document's top-level block nodes, in reading order.
	Content []PromptNode `json:"content"`

	// Type Discriminates this object as a prompt document's root node.
	Type PromptDocumentType `json:"type"`
}

// PromptDocumentType Discriminates this object as a prompt document's root node.
type PromptDocumentType string

// PromptMark An inline formatting mark applied to a prompt document's text node.
type PromptMark struct {
	// Attrs Mark-specific attributes (e.g. link's href; textStyle's color
	// and/or backgroundColor as CSS color strings). Absent when the
	// mark type has none set.
	Attrs *map[string]interface{} `json:"attrs,omitempty"`

	// Type The kind of mark this is. textStyle carries a chosen font color,
	// background color, or both — never both fixed and absent at
	// once; highlight remains the separate, single-color emphasis
	// mark it already was.
	Type PromptMarkType `json:"type"`
}

// PromptMarkType The kind of mark this is. textStyle carries a chosen font color,
// background color, or both — never both fixed and absent at
// once; highlight remains the separate, single-color emphasis
// mark it already was.
type PromptMarkType string

// PromptNode A single node in a prompt document's tree. Container node types
// (heading, paragraph, list and table nodes) nest further nodes under
// content; the text node is a leaf that carries the literal string
// under text and any inline marks under marks. attrs holds
// type-specific attributes (e.g. heading's level, paragraph/heading's
// text alignment, image's src and alt, audio/video's src, diagram's
// diagramRef or diagramStackRef, table cell's colspan, rowspan,
// backgroundColor, and borderColor) and is validated by the authoring
// editor, not by this schema. attrs keys are camelCase (the rich-text
// editor's convention), so a diagram node's keys are diagramRef and
// diagramStackRef — not diagram_ref/diagram_stack_ref. Their values
// are the DiagramRef/DiagramStackRef shapes defined elsewhere in this
// spec, whose own fields stay snake_case (diagram_id, layers, …).
type PromptNode struct {
	// Attrs Type-specific attributes for this node. Absent when the node
	// type has none set.
	Attrs *map[string]interface{} `json:"attrs,omitempty"`

	// Content Child nodes, present on container node types. Absent on leaf
	// node types (text, image).
	Content *[]PromptNode `json:"content,omitempty"`

	// Marks Inline formatting marks applied to this node. Present only on
	// text nodes that carry at least one mark.
	Marks *[]PromptMark `json:"marks,omitempty"`

	// Text The literal text content. Present only when type is text.
	Text *string `json:"text,omitempty"`

	// Type The kind of node this is. audio, video, and diagram are
	// available to rich_text expanded content and remediation
	// content; the exercise-prompt authoring toolbar does not offer
	// audio/video, but does offer diagram — a diagram can be embedded
	// inline in any PromptDocument, including an exercise's own
	// prompt. songChart embeds a published song chart, and is
	// available only in lesson content: an article's body and
	// rich_text expanded content. Its attrs hold songChartId, the
	// chart's id (a UUID). It always shows the chart's latest
	// published revision; a chart withdrawn after it was embedded
	// shows to nobody. A songChart node naming a chart that doesn't
	// exist, or was never published, is refused when the content is
	// saved.
	Type PromptNodeType `json:"type"`
}

// PromptNodeType The kind of node this is. audio, video, and diagram are
// available to rich_text expanded content and remediation
// content; the exercise-prompt authoring toolbar does not offer
// audio/video, but does offer diagram — a diagram can be embedded
// inline in any PromptDocument, including an exercise's own
// prompt. songChart embeds a published song chart, and is
// available only in lesson content: an article's body and
// rich_text expanded content. Its attrs hold songChartId, the
// chart's id (a UUID). It always shows the chart's latest
// published revision; a chart withdrawn after it was embedded
// shows to nobody. A songChart node naming a chart that doesn't
// exist, or was never published, is refused when the content is
// saved.
type PromptNodeType string

// RegisterUserRequest Payload for registering a new MotifPath user.
type RegisterUserRequest struct {
	// Role The role this Clerk identity will hold in the platform. A student
	// consumes content and emits tracking events. A teacher creates content
	// and manages learning paths. Cannot be changed after registration.
	//
	// The admin role is not self-registrable. Admin accounts are provisioned
	// directly in the database at deploy time and are reserved for internal
	// platform operations.
	Role RegisterUserRequestRole `json:"role"`
}

// RegisterUserRequestRole The role this Clerk identity will hold in the platform. A student
// consumes content and emits tracking events. A teacher creates content
// and manages learning paths. Cannot be changed after registration.
//
// The admin role is not self-registrable. Admin accounts are provisioned
// directly in the database at deploy time and are reserved for internal
// platform operations.
type RegisterUserRequestRole string

// RemediationTarget One piece of content recommended to a student who answers a
// specific exercise incorrectly. Exactly one of content_node_id or
// rich_content must be present — a target is either a reference to an
// existing content node already published on the platform, or
// inline-authored content (for example, a specific external video or
// article, with a caption explaining why it's suggested) using the
// same rich-content model as an exercise prompt.
type RemediationTarget struct {
	// Caption Optional short label shown alongside this target (e.g. "Watch
	// this if the chord shapes felt unfamiliar"). Applies to either
	// target shape.
	Caption *string `json:"caption,omitempty"`

	// ContentNodeId An existing content node to recommend. Must be absent if
	// rich_content is present.
	ContentNodeId *openapi_types.UUID `json:"content_node_id,omitempty"`

	// RichContent A structured rich-text document, authored with MotifPath's
	// Tiptap-based content-authoring editor and persisted exactly as the
	// editor produces it (ProseMirror JSON). Used for an exercise's
	// prompt, rich_text expanded content, and an exercise's
	// remediation_targets rich content — the same document shape across
	// all three, though which PromptNode types a given surface's own
	// toolbar can actually produce varies (an exercise prompt's toolbar
	// does not offer audio/video embeds; expanded content and remediation
	// content may). Always has type "doc" at the root, with the
	// document's block-level content nested beneath it.
	RichContent *PromptDocument `json:"rich_content,omitempty"`
}

// ReplaceCourseRequest Payload for replacing a course's draft wholesale.
type ReplaceCourseRequest struct {
	Checkpoints []struct {
		// LearningPathId The learning path template at this checkpoint. Must exist in the system. It may be a draft while the course is being built, but the course can't be published until it is published.
		LearningPathId openapi_types.UUID `json:"learning_path_id"`

		// Title Optional override shown for this checkpoint instead of the learning path's own title.
		Title *string `json:"title,omitempty"`
	} `json:"checkpoints"`

	// InstrumentIds The instruments this item is for, by Instrument.instrument_id. An
	// empty list means it suits every instrument (for example, music
	// theory). Every id must reference an existing instrument, and none
	// may repeat.
	InstrumentIds InstrumentIds `json:"instrument_ids"`

	// Language The language the course is written in, as a Language.code other than "any". A course is not localized: its title, summary and checkpoint titles are all in this language.
	Language string `json:"language"`

	// Level The level a student should be at to start this course, using the same five-value rubric applied to content nodes.
	Level ReplaceCourseRequestLevel `json:"level"`

	// Summary Short description of the course shown in the catalog.
	Summary string `json:"summary"`

	// ThumbnailUrl An image shown for this item in lists and cards, as an absolute http or https URL (typically one returned by POST /media/upload-url with purpose thumbnail). Omitted means no thumbnail; on a replace or update, omitting it removes the current one.
	ThumbnailUrl *string `json:"thumbnail_url,omitempty"`

	// Title Title of the course.
	Title string `json:"title"`
}

// ReplaceCourseRequestLevel The level a student should be at to start this course, using the same five-value rubric applied to content nodes.
type ReplaceCourseRequestLevel string

// ReplaceLearningPathRequest Payload for replacing an existing learning path's title and items
// wholesale — the same shape as CreateLearningPathRequest, since a
// change to any single item (add, remove, reorder, relabel) is
// expressed by resending the complete desired items array.
type ReplaceLearningPathRequest struct {
	// InstrumentIds The instruments this item is for, by Instrument.instrument_id. An
	// empty list means it suits every instrument (for example, music
	// theory). Every id must reference an existing instrument, and none
	// may repeat.
	InstrumentIds InstrumentIds `json:"instrument_ids"`

	// Items Ordered list of content nodes that make up this path. At least one item is required.
	Items []struct {
		// ContentNodeId The ID of the content node at this position. Must exist in the system.
		ContentNodeId openapi_types.UUID `json:"content_node_id"`

		// SectionLabel Optional label grouping this item with its immediate neighbors under a named section in the resulting path view.
		SectionLabel *string `json:"section_label,omitempty"`
	} `json:"items"`

	// Language The language the path is written in, as a Language.code other than "any". Optional while the path is a draft; omitting it removes the current one. Required to publish.
	Language *string `json:"language,omitempty"`

	// Level The level a learner should be at to follow this path, using the same five-value rubric applied to courses and content nodes.
	Level ReplaceLearningPathRequestLevel `json:"level"`

	// Summary Short description of the path shown in the path catalog. Optional while the path is a draft; omitting it removes the current one. Required to publish.
	Summary *string `json:"summary,omitempty"`

	// ThumbnailUrl An image shown for this item in lists and cards, as an absolute http or https URL (typically one returned by POST /media/upload-url with purpose thumbnail). Omitted means no thumbnail; on a replace or update, omitting it removes the current one.
	ThumbnailUrl *string `json:"thumbnail_url,omitempty"`

	// Title Human-readable name for this learning path, displayed to teachers and admins.
	Title string `json:"title"`
}

// ReplaceLearningPathRequestLevel The level a learner should be at to follow this path, using the same five-value rubric applied to courses and content nodes.
type ReplaceLearningPathRequestLevel string

// RightsConfirmation An admin's statement that a song's rights were checked. Rights are
// cleared outside MotifPath; this records only who confirmed it, and
// when.
type RightsConfirmation struct {
	// ConfirmedAt When the rights were confirmed.
	ConfirmedAt time.Time `json:"confirmed_at"`

	// ConfirmedBy A reference to another MotifPath user, as it appears in any response
	// that points at a user (ADR-035). display_name is read from the
	// user's record when the response is built, never copied onto the
	// referencing entity, so a rename shows everywhere at once. A UserRef
	// appears only in responses the caller is already authorized to
	// receive.
	ConfirmedBy UserRef `json:"confirmed_by"`
}

// SequenceStep One step of a diagram playback. Its positions start together (or
// strummed), sound for the step's value, and the next step starts
// when this one ends. A step with no positions is a rest.
type SequenceStep struct {
	// PositionIds The positions that sound in this step, each a position of the
	// diagram and each at most once per step. Empty makes the step a
	// rest.
	PositionIds []openapi_types.UUID `json:"position_ids"`

	// Strum How a step's positions start: none starts them together; down
	// starts the lowest pitch first and up the highest first, a few
	// milliseconds apart, as a pick crossing the strings. The first
	// note starts on the beat. Has no effect on a step with fewer than
	// two positions.
	Strum *SequenceStepStrum `json:"strum,omitempty"`

	// Value A length as a fraction of a whole note: 1/4 is a quarter note, 3/8 a
	// dotted quarter, 1/16 a sixteenth. Tuplets are plain fractions too: n
	// notes in the time of m notes of 1/d are each m/(n×d), so an
	// eighth-note triplet is 1/12 and a sixteenth-note sextuplet 1/24.
	Value NoteValue `json:"value"`
}

// SequenceStepStrum How a step's positions start: none starts them together; down
// starts the lowest pitch first and up the highest first, a few
// milliseconds apart, as a pick crossing the strings. The first
// note starts on the beat. Has no effect on a step with fewer than
// two positions.
type SequenceStepStrum string

// SetCurrentPathRequest Payload for switching the caller's current course or path. Exactly one of course_enrollment_id or student_path_id must be given.
type SetCurrentPathRequest struct {
	// CourseEnrollmentId An active CourseEnrollment already belonging to the caller, to make current.
	CourseEnrollmentId *openapi_types.UUID `json:"course_enrollment_id,omitempty"`

	// StudentPathId A non-archived standalone StudentPath already belonging to the caller, to make current.
	StudentPathId *openapi_types.UUID `json:"student_path_id,omitempty"`
}

// ShapeInterval A diagram position's interval code, as in Position.interval. In a find the degree
// response, the degree that was asked: one of the shape's intervals other than R, since
// the root is shown.
type ShapeInterval string

// SkillProgress How one skill improved over the last 7 days, with both values so the student sees
// where they started (for example accuracy 0.72 → 0.86).
type SkillProgress struct {
	// After The value now.
	After float32 `json:"after"`

	// Before The value 7 days ago, at the end of the day before the last 7 calendar days in
	// the given time zone. An accuracy or fluency starts from 0 for a skill first
	// practised since then; a tempo line needs a clean take on both sides.
	Before float32 `json:"before"`

	// Measure What improved. accuracy and fluency are ratios from 0 to 1 over the skill's
	// practised items; best_clean_tempo_bpm is a tempo.
	Measure SkillProgressMeasure `json:"measure"`

	// Names Text in one or more languages, keyed by Language.code — for example
	// {"en": "Guitar", "pt_BR": "Violão"}. "any" is never a key: a name is
	// always words in some language. Clients display the name for the
	// viewer's locale, falling back to "en", then to any name present.
	Names LocalizedNames `json:"names"`

	// NodeId The skill.
	NodeId openapi_types.UUID `json:"node_id"`
}

// SkillProgressMeasure What improved. accuracy and fluency are ratios from 0 to 1 over the skill's
// practised items; best_clean_tempo_bpm is a tempo.
type SkillProgressMeasure string

// SongChart A song chart as admins see it: its draft and what learners are
